  1737  SignatureInfo *FormFieldSignature::validateSignature(bool doVerifyCert, bool forceRevalidation, time_t validationTime)
  1738  {
  1739  #ifdef ENABLE_NSS3
  1740    if (!signature_info->isSubfilterSupported()) {
  1741      error(errUnimplemented, 0, "Unable to validate this type of signature");
  1742      return signature_info;
  1743    }
  1744
  1745    if (signature_info->getSignatureValStatus() != SIGNATURE_NOT_VERIFIED && !forceRevalidation) {
  1746      return signature_info;
  1747    }
  1748
  1749    if (signature == nullptr) {
  1750      error(errSyntaxError, 0, "Invalid or missing Signature string");
  1751      return signature_info;
  1752    }
  1753
  1754    if (!byte_range.isArray()) {
  1755      error(errSyntaxError, 0, "Invalid or missing ByteRange array");
  1756      return signature_info;
  1757    }
  1758
  1759    int arrayLen = byte_range.arrayGetLength();
  1760    if (arrayLen < 2) {
  1761      error(errSyntaxError, 0, "Too few elements in ByteRange array");
  1762      return signature_info;
  1763    }
  1764
  1765    const int signature_len = signature->getLength();
  1766    unsigned char *signatureuchar = (unsigned char *)gmalloc(signature_len);
  1767    memcpy(signatureuchar, signature->c_str(), signature_len);
  1768    SignatureHandler signature_handler(signatureuchar, signature_len);
  1769
  1770    Goffset fileLength = doc->getBaseStream()->getLength();
  1771    for (int i = 0; i < arrayLen/2; i++) {
  1772      Object offsetObj = byte_range.arrayGet(i*2);
  1773      Object lenObj = byte_range.arrayGet(i*2+1);
  1774
  1775      if (!offsetObj.isIntOrInt64() || !lenObj.isIntOrInt64()) {
  1776        error(errSyntaxError, 0, "Illegal values in ByteRange array");
  1777        return signature_info;
  1778      }
  1779
  1780      Goffset offset = offsetObj.getIntOrInt64();
  1781      Goffset len = lenObj.getIntOrInt64();
  1782
  1783      if (offset < 0 || offset >= fileLength || len < 0 || len > fileLength || offset + len > fileLength) {
  1784        error(errSyntaxError, 0, "Illegal values in ByteRange array");
  1785        return signature_info;
  1786      }
  1787
  1788      doc->getBaseStream()->setPos(offset);
  1789      hashSignedDataBlock(&signature_handler, len);
  1790    }
  1791
  1792    const SignatureValidationStatus sig_val_state = signature_handler.validateSignature();
  1793    signature_info->setSignatureValStatus(sig_val_state);
  1794    signature_info->setSignerName(signature_handler.getSignerName());
  1795    signature_info->setSubjectDN(signature_handler.getSignerSubjectDN());
  1796    signature_info->setHashAlgorithm(signature_handler.getHashAlgorithm());
  1797
  1798    // verify if signature contains a 'signing time' attribute
  1799    if (signature_handler.getSigningTime() != 0) {
  1800      signature_info->setSigningTime(signature_handler.getSigningTime());
  1801    }
  1802
  1803    if (sig_val_state != SIGNATURE_VALID || !doVerifyCert) {
  1804      return signature_info;
  1805    }
  1806
  1807    const CertificateValidationStatus cert_val_state = signature_handler.validateCertificate(validationTime);
  1808    signature_info->setCertificateValStatus(cert_val_state);
  1809    signature_info->setCertificateInfo(signature_handler.getCertificateInfo());
  1810
  1811  #endif
  1812    return signature_info;
  1813  }
