  1917  // Look up an inheritable field dictionary entry.
  1918  static Object fieldLookup(Dict *field, const char *key, std::set<int> *usedParents) {
  1919    Dict *dict = field;
  1920    Object obj = dict->lookup(key);
  1921    if (!obj.isNull()) {
  1922      return obj;
  1923    }
  1924    const Object &parent = dict->lookupNF("Parent");
  1925    if (parent.isRef()) {
  1926      const Ref ref = parent.getRef();
  1927      if (usedParents->find(ref.num) == usedParents->end()) {
  1928        usedParents->insert(ref.num);
  1929
  1930        Object obj2 = parent.fetch(dict->getXRef());
  1931        if (obj2.isDict()) {
  1932          return fieldLookup(obj2.getDict(), key, usedParents);
  1933        }
  1934      }
  1935    } else if (parent.isDict()) {
  1936      return fieldLookup(parent.getDict(), key, usedParents);
  1937    }
  1938    return Object(objNull);
  1939  }
