  1946  FormField *Form::createFieldFromDict (Object &&obj, PDFDoc *docA, const Ref aref, FormField *parent, std::set<int> *usedParents)
  1947  {
  1948      FormField *field;
  1949
  1950      const Object obj2 = Form::fieldLookup(obj.getDict (), "FT");
  1951      if (obj2.isName("Btn")) {
  1952        field = new FormFieldButton(docA, std::move(obj), aref, parent, usedParents);
  1953      } else if (obj2.isName("Tx")) {
  1954        field = new FormFieldText(docA, std::move(obj), aref, parent, usedParents);
  1955      } else if (obj2.isName("Ch")) {
  1956        field = new FormFieldChoice(docA, std::move(obj), aref, parent, usedParents);
  1957      } else if (obj2.isName("Sig")) {
  1958        field = new FormFieldSignature(docA, std::move(obj), aref, parent, usedParents);
  1959      } else { //we don't have an FT entry => non-terminal field
  1960        field = new FormField(docA, std::move(obj), aref, parent, usedParents);
  1961      }
  1962
  1963      return field;
  1964  }
